  if(d.unsupported?.length)warnings.push(`Có lệnh mở rộng chưa dựng trực tiếp: ${d.unsupported.map(x=>'\\'+x).join(', ')}.`);
  return {errors:[...new Set(errors)],warnings:[...new Set(warnings)]};
