/* ---------- Transfer between classes owned by the same teacher ---------- */
async function v27PruneUidFromGroups(classId,uid){
  try{let snap=await v27GroupsRef(classId).get(),affected=snap.docs.filter(d=>(d.data()?.memberUids||[]).includes(uid));if(!affected.length)return 0;let b=firebaseDb.batch();affected.forEach(d=>{let g=d.data()||{},uids=(g.memberUids||[]).filter(x=>x!==uid);b.set(d.ref,{memberUids:uids,memberCount:uids.length,schemaVersion:27,updatedAt:firebaseServerTimestamp()},{merge:true})});await b.commit();v27InvalidateGroups(classId);return affected.length}catch(err){console.warn(' prune groups',err);return 0}
}
