/* ===== assets/js/student-ux-v28.js ===== */
/* Math12 Hub  — Student Learning UX
   Personal goal, next-best-action queue, dynamic 7-day plan, mistake notebook.
    self-study focus: recommendations use only questions/codes that exist in the current learner bank; online-class assignments are excluded. */
const V28_DEFAULT_PLAN={targetScore:8,dailyMinutes:35,weeklyDays:5,updatedAt:''};
let v28ActionCache=[];
function v383PracticeBank(){return window.V383PracticeBank?.effectiveBank?.()||window.V3822PracticeBank?.effectiveBank?.({approvedOnly:false})||(state.questionBank||[])}
function v383BankIds(){return new Set(v383PracticeBank().map(q=>q?.id).filter(Boolean))}
function v383BankCodes(){return new Set(v383PracticeBank().map(q=>q?.knowledgeCode).filter(Boolean))}
function v383BankLessons(){return new Set(v383PracticeBank().map(q=>q?.lessonId).filter(Boolean))}

function v28EnsurePlan(){
  const p=state.studentPlanV28&&typeof state.studentPlanV28==='object'?state.studentPlanV28:{};
  state.studentPlanV28={
    targetScore:Math.min(10,Math.max(5,Number(p.targetScore)||V28_DEFAULT_PLAN.targetScore)),
    dailyMinutes:Math.min(90,Math.max(15,Number(p.dailyMinutes)||V28_DEFAULT_PLAN.dailyMinutes)),
    weeklyDays:Math.min(7,Math.max(2,Number(p.weeklyDays)||V28_DEFAULT_PLAN.weeklyDays)),
    updatedAt:typeof p.updatedAt==='string'?p.updatedAt:''
  };
  return state.studentPlanV28;
}
function v28Plan(){return v28EnsurePlan()}
function v28DateKey(d=new Date()){let x=d instanceof Date?d:new Date(d);return Number.isNaN(x.getTime())?'':`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`}
function v28DateLabel(d){return new Intl.DateTimeFormat('vi-VN',{weekday:'short',day:'2-digit',month:'2-digit'}).format(d).replace('Th ','T')}
function v28RecentActivityKeys(){
  const keys=new Set();
  (state.examAttempts||[]).forEach(x=>{let d=new Date(x.date||0);if(!Number.isNaN(d.getTime()))keys.add(v28DateKey(d))});
  (state.questionHistory||[]).forEach(x=>{let d=new Date(x.date||0);if(!Number.isNaN(d.getTime()))keys.add(v28DateKey(d))});
  return keys
}
function v28MistakeItems(limit=50){
  const latest=new Map(),ids=v383BankIds(),codes=v383BankCodes();
  analyticsHistory().forEach(h=>{if(h.questionId&&!ids.has(h.questionId)&&!codes.has(h.code))return;if(!h.questionId&&!codes.has(h.code))return;let id=h.questionId||`${h.code}|${h._idx}`;let old=latest.get(id);if(!old||String(h.date||'')>=String(old.date||''))latest.set(id,h)});
  return [...latest.values()].filter(h=>Number(h.credit)<.999).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,limit)
}
function v28MistakeCodes(){
  const map=new Map();v28MistakeItems(100).forEach(h=>{let x=map.get(h.code)||{code:h.code,title:h.title||h.code,count:0,credit:0};x.count++;x.credit+=Number(h.credit)||0;map.set(h.code,x)});
  return [...map.values()].sort((a,b)=>b.count-a.count||a.credit/a.count-b.credit/b.count)
}
function v28AverageScore(){let s=(state.examAttempts||[]).map(x=>Number(x.score)).filter(Number.isFinite);return s.length?s.reduce((a,b)=>a+b,0)/s.length:null}
function v28Readiness(){
  const a=analyticsOverallStats(),avg=v28AverageScore(),completion=TOTAL?state.done.length/TOTAL:0,accuracy=a.accuracy==null?0:a.accuracy,score=avg==null?0:Math.max(0,Math.min(1,avg/10)),streak=Math.min(1,learningStreakDays()/5),evidence=Math.min(1,a.total/40);
  const hasEvidence=a.total>0||(state.examAttempts||[]).length>0||state.done.length>0;
  let value=Math.round(100*(.28*completion+.32*accuracy+.20*score+.10*streak+.10*evidence));
  if(!hasEvidence)value=0;
  return {value,completion,accuracy:a.accuracy,avg,evidence:a.total,label:value>=80?'Đang đi đúng mục tiêu':value>=60?'Nền tảng khá':value>=35?'Đang xây nền':'Cần bắt đầu tích lũy dữ liệu'}
}
function v28AssignmentState(a,now=Date.now()){
  const open=firebaseToDate?.(a.opensAt),due=firebaseToDate?.(a.dueAt),submitted=!!a.submission,graded=submitted&&a.submission.score!=null;
  return {open,due,submitted,graded,isFuture:!!open&&open.getTime()>now,isOver:!!due&&due.getTime()<now,isOpen:(!open||open.getTime()<=now)&&(!due||due.getTime()>=now)}
}
function v28NextIncompleteLessons(){return chapters.flatMap(c=>c.lessons).filter(l=>!state.done.includes(l.id))}
function v28Queue(){
  const plan=v28Plan(),q=[],bank=v383PracticeBank(),codes=v383BankCodes(),lessons=v383BankLessons();
  const mistakes=v28MistakeItems(50),mistakeCodes=v28MistakeCodes();
  if(mistakes.length)q.push({priority:1,kind:'mistakes',title:`Luyện lại ${mistakes.length} câu còn sai`,meta:mistakeCodes.slice(0,2).map(x=>displayKnowledgeCode(x.code)).join('')||'Sổ câu sai',reason:'Ôn lại lỗi cũ trước khi học thêm giúp giảm lặp lại sai sót.',minutes:Math.min(plan.dailyMinutes,Math.max(15,mistakes.length*2))});
  const weak=(analyticsWeakSkills(20)||[]).filter(x=>codes.has(x.code));
  const w=weak.find(x=>x.total>=2&&x.accuracy<.8)||weak[0];
  if(w)q.push({priority:2,kind:'weak',title:`Củng cố ${w.title||'kiến thức cần luyện'}`,meta:`${displayKnowledgeCode(w.code)} • ${w.total} lượt • ${w.accuracy==null?'—':Math.round(w.accuracy*100)+'%'}`,reason:'Đây là mã kiến thức có kết quả thấp và đang có câu trong ngân hàng.',minutes:Math.min(plan.dailyMinutes,25),code:w.code});
  const next=v28NextIncompleteLessons().find(l=>lessons.has(l.id));
  if(next)q.push({priority:3,kind:'lesson',title:`Học tiếp: ${next.common}`,meta:`${next.id} • ${bank.filter(x=>x.lessonId===next.id).length} câu trong ngân hàng`,reason:'Tiếp tục hoàn thành bài có dữ liệu luyện tập thực tế.',minutes:Math.min(plan.dailyMinutes,getLessonMeta(next.id).minutes||45),lessonId:next.id});
  if(!q.length){const firstLesson=[...lessons][0];if(firstLesson){const l=getLesson(firstLesson);q.push({priority:5,kind:'lesson',title:`Ôn ${l?.common||firstLesson}`,meta:`${bank.filter(x=>x.lessonId===firstLesson).length} câu trong ngân hàng`,reason:'Bắt đầu từ bài đang có dữ liệu.',minutes:plan.dailyMinutes,lessonId:firstLesson})}else q.push({priority:9,kind:'exam',title:'Làm đề mô phỏng THPT',meta:'Đề tổng hợp',reason:'Kiểm tra năng lực tổng hợp.',minutes:90})}
  return q.sort((a,b)=>a.priority-b.priority||a.minutes-b.minutes)
}
function v28RunAction(i=0){
  const x=v28ActionCache[Number(i)]||v28Queue()[Number(i)]||v28Queue()[0];if(!x)return;
  if(x.kind==='mistakes')return v28PracticeMistakes(10);
  if(x.kind==='weak')return startAdaptivePractice(10,x.code);
  if(x.kind==='lesson')return openLesson(x.lessonId);
  if(x.kind==='exam')return openFullExam();
}
function v28StartNextAction(){v28ActionCache=v28Queue();return v28RunAction(0)}
function v28PracticeMistakes(count=10){
  count=Math.max(1,Math.min(30,Number(count)||10));const mistakes=v28MistakeItems(120),ids=new Set(mistakes.map(x=>x.questionId).filter(Boolean)),codes=[...new Set(mistakes.map(x=>x.code).filter(Boolean))],bank=v383PracticeBank();
  let pool=bank.filter(q=>ids.has(q.id)&&['mcq','tf','tf4','short'].includes(q.type));
  if(pool.length<count){for(const q of bank){if(pool.length>=count)break;if(codes.includes(q.knowledgeCode)&&!pool.some(x=>x.id===q.id)&&['mcq','tf','tf4','short'].includes(q.type))pool.push(q)}}
  if(pool.length<1){if(codes[0])return startAdaptivePractice(count,codes[0]);return alert('Chưa có câu sai nào thuộc ngân hàng tự học hiện tại.')}
  let selected=examShuffle(pool,Date.now()).slice(0,count),config={id:`mistake-retry-${Date.now()}`,mode:'adaptive',attemptType:'mistake-retry',title:'Luyện lại câu sai',subtitle:`${selected.length} câu • lấy từ ngân hàng tự học${codes.length?''+codes.slice(0,4).map(displayKnowledgeCode).join(''):''}`,durationMinutes:Math.max(8,Math.ceil(selected.length*1.8)),questions:selected.map(q=>normalizeBankQuestion(q,'Luyện lại câu sai')),scoring:'standard',adaptiveCodes:codes.slice(0,4)};openExamStart(config)
}
function v28OpenPlanSettings(){
  const p=v28Plan();openModal('Mục tiêu học tập','Cấu hình lộ trình cá nhân; dữ liệu được đồng bộ cùng tiến độ học.',`<div class="firebase-banner"><b>Gợi ý:</b> đặt mục tiêu vừa sức và duy trì đều. Chỉ báo  là công cụ định hướng, không dự đoán điểm thi.</div><div class="online-form mt"><label>Mục tiêu điểm</label><select id="v28GoalScore">${[5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10].map(n=>`<option value="${n}" ${Number(p.targetScore)===n?'selected':''}>${n.toFixed(1)}+</option>`).join('')}</select><label>Thời lượng mỗi ngày</label><select id="v28DailyMinutes">${[15,20,25,30,35,40,45,60,75,90].map(n=>`<option value="${n}" ${Number(p.dailyMinutes)===n?'selected':''}>${n} phút</option>`).join('')}</select><label>Số ngày học mỗi tuần</label><select id="v28WeeklyDays">${[2,3,4,5,6,7].map(n=>`<option value="${n}" ${Number(p.weeklyDays)===n?'selected':''}>${n} ngày/tuần</option>`).join('')}</select></div>`,`<button class="btn btn-soft" onclick="closeModal()">Hủy</button><button class="btn btn-blue" onclick="v28SavePlanSettings()">Lưu mục tiêu</button>`)
}
function v28SavePlanSettings(){
  state.studentPlanV28={targetScore:Number(document.getElementById('v28GoalScore')?.value)||8,dailyMinutes:Number(document.getElementById('v28DailyMinutes')?.value)||35,weeklyDays:Number(document.getElementById('v28WeeklyDays')?.value)||5,updatedAt:new Date().toISOString()};save();closeModal();renderAll();examToast?.('Đã cập nhật mục tiêu học tập .')
}
function v28WeeklyPlan(){
  const p=v28Plan(),queue=v28Queue(),weak=(analyticsWeakSkills(20)||[]).filter(x=>v383BankCodes().has(x.code)),mist=v28MistakeItems(50),lessons=v28NextIncompleteLessons().filter(l=>v383BankLessons().has(l.id)),out=[],activity=v28RecentActivityKeys(),today=new Date();today.setHours(0,0,0,0);
  let wi=0,li=0;
  for(let i=0;i<7;i++){
    let d=new Date(today);d.setDate(d.getDate()+i);let key=v28DateKey(d),task=null;
    if(i===0&&queue[0])task={...queue[0]};
    else if(mist.length&&i%3===1)task={title:'Ôn sổ câu sai',meta:`${Math.min(mist.length,10)} câu • ${Math.min(p.dailyMinutes,25)} phút`,kind:'mistakes'};
    else if(weak.length&&i%2===0){let w=weak[wi++%weak.length];task={title:`Củng cố ${w.title||'kiến thức cần luyện'}`,meta:`${displayKnowledgeCode(w.code)} • ${Math.min(p.dailyMinutes,25)} phút`,kind:'weak',code:w.code}}
    else if(lessons.length){let l=lessons[li++%lessons.length];task={title:l.common,meta:`${l.id} • ${v383PracticeBank().filter(q=>q.lessonId===l.id).length} câu`,kind:'lesson',lessonId:l.id}}
    else task={title:'Ôn tổng hợp / đề ngắn',meta:`${p.dailyMinutes} phút`,kind:'exam'};
    let activeDay=i<p.weeklyDays,status=activity.has(key)?'done':activeDay?'planned':'light';out.push({date:d,key,activeDay,status,...task})
  }
  return out
}
function v28RenderQueue(targetId='v28TodayQueue',limit=4){
  const box=document.getElementById(targetId);if(!box)return;v28ActionCache=v28Queue();const q=v28ActionCache.slice(0,limit);box.innerHTML=q.map((x,i)=>`<div class="v28-queue-item ${i===0?'primary':''}"><div class="v28-queue-rank">${i+1}</div><div><b>${esc(x.title)}</b><small>${esc(x.meta||x.reason||'')}</small></div><button class="btn ${i===0?'btn-blue':'btn-soft'}" onclick="v28RunAction(${i})">${x.kind==='lesson'?'Học':x.kind==='exam'?'Thi':'Luyện'}</button></div>`).join('')
}
function v28RenderMistakes(targetId='v28MistakeBook',limit=6){
  const box=document.getElementById(targetId);if(!box)return;const rows=v28MistakeCodes().slice(0,limit),total=v28MistakeItems(100).length;box.innerHTML=rows.length?`<div class="v28-mistake-summary"><div><b>${total}</b><small>Câu còn sai theo lần làm gần nhất</small></div><button class="btn btn-blue" onclick="v28PracticeMistakes(10)">Luyện lại 10 câu</button></div><div class="v28-mistake-list">${rows.map(x=>`<div><span class="skill-code">${esc(displayKnowledgeCode(x.code))}</span><b>${esc(x.title)}</b><small>${x.count} câu cần xem lại</small><button class="btn btn-soft" onclick="startAdaptivePractice(6,'${attrEsc(x.code)}')">Luyện mã này</button></div>`).join('')}</div>`:'<div class="v28-empty-good"><b>✓ Chưa có câu sai tồn đọng.</b><span>Làm thêm bài kiểm tra để  tạo sổ lỗi theo lần làm gần nhất.</span></div>'
}
function v28RenderWeek(targetId='v28WeeklyPlan'){
  const box=document.getElementById(targetId);if(!box)return;const week=v28WeeklyPlan();box.innerHTML=`<div class="v28-week-grid">${week.map((x,i)=>`<div class="v28-day ${x.status}"><div class="v28-day-head"><b>${v28DateLabel(x.date)}</b><span>${x.status==='done'?'✓ Có học':x.status==='light'?'Nghỉ/ôn nhẹ':'Gợi ý'}</span></div><strong>${esc(x.title)}</strong><small>${esc(x.meta||'')}</small>${x.status!=='done'&&x.status!=='light'?`<button class="link-btn" onclick="v28RunWeekAction(${i})">Bắt đầu →</button>`:''}</div>`).join('')}</div>`
}
function v28RunWeekAction(i){const x=v28WeeklyPlan()[Number(i)];if(!x)return;if(x.kind==='mistakes')return v28PracticeMistakes(10);if(x.kind==='weak')return startAdaptivePractice(8,x.code);if(x.kind==='lesson')return openLesson(x.lessonId);return openFullExam()}
function v28RenderStudentUX(){
  if(typeof isTeacherRole==='function'&&isTeacherRole())return;const p=v28Plan(),r=v28Readiness(),q=v28Queue(),first=q[0],mist=v28MistakeItems(100).length,weak=analyticsWeakSkills(20).filter(x=>v383BankCodes().has(x.code)&&x.total>=2&&x.accuracy<.8).length;
  const text=(id,val)=>{let e=document.getElementById(id);if(e)e.textContent=val},html=(id,val)=>{let e=document.getElementById(id);if(e)e.innerHTML=val};
  text('v28GoalScoreHero',`${Number(p.targetScore).toFixed(1)}+`);text('v28GoalScore',`${Number(p.targetScore).toFixed(1)}+`);text('v28DailyGoal',`${p.dailyMinutes} phút`);text('v28WeeklyGoal',`${p.weeklyDays} ngày`);text('v28ReadinessValue',`${r.value}%`);text('v28ReadinessLabel',r.label);let bar=document.getElementById('v28ReadinessBar');if(bar)bar.style.width=`${r.value}%`;
  text('v28MistakeMetric',mist);text('v28WeakMetric',weak);text('v28PriorityMetric',q.filter(x=>x.priority<=1).length);
  if(first){text('v28NextActionTitle',first.title);text('v28NextActionTitlePlan',first.title);text('v28NextActionMeta',first.meta||`${first.minutes||p.dailyMinutes} phút`);text('v28NextActionReason',first.reason||'Đây là bước ưu tiên tiếp theo theo dữ liệu hiện có.');let b=document.getElementById('v28NextActionBtn');if(b)b.textContent=first.kind==='lesson'?'Học tiếp':first.kind==='exam'?'Thi thử':'Bắt đầu luyện'}
  v28RenderQueue('v28TodayQueue',4);v28RenderQueue('v28PlanQueue',6);v28RenderMistakes('v28MistakeBook',6);v28RenderMistakes('v28PlanMistakes',8);v28RenderWeek('v28WeeklyPlan');v28RenderWeek('v28PlanWeek');
  const summary=`<div class="v28-plan-summary"><div><small>Mục tiêu</small><b>${Number(p.targetScore).toFixed(1)}+</b></div><div><small>Nhịp học</small><b>${p.dailyMinutes}' × ${p.weeklyDays} ngày</b></div><div><small>Chỉ báo lộ trình</small><b>${r.value}%</b></div><button class="btn btn-soft" onclick="v28OpenPlanSettings()">Điều chỉnh</button></div>`;html('v28ProgressPlanSummary',summary);html('v28ProgressSummary',summary)
}


/* ===== assets/js/avatar-compat-v40.15.9.js ===== */
/* =========================================================
   Math12 Hub  — Avatar Foundation
   - Student-only starter avatar profile.
   - First authenticated student login asks for Male/Female starter path.
   - Starter customization: skin, face, hair and basic outfit.
   - Local-first persistence + optional Firestore user-profile sync.
   - No EXP / gold / shop economy yet (reserved for +).
   ========================================================= */
const AVATAR_V378_SCHEMA=1;
const AVATAR_V378_RANK='Tân binh Toán học';
const AVATAR_V378_STARTER_LEVEL=1;
const AVATAR_V378_SKINS={
  light:{label:'Sáng',fill:'#F4C7A1',shadow:'#D99B72'},
  warm:{label:'Ấm',fill:'#E6AD7B',shadow:'#C47C52'},
  tan:{label:'Nâu',fill:'#B97850',shadow:'#8F5335'}
};
const AVATAR_V378_FACES={
  smile:{label:'Vui vẻ'},
  calm:{label:'Điềm tĩnh'},
  confident:{label:'Tự tin'},
  focus:{label:'Tập trung'}
};
const AVATAR_V378_HAIR={
  male:[
    {id:'short',label:'Gọn gàng'},
    {id:'side',label:'Rẽ ngôi'},
    {id:'spiky',label:'Năng động'}
  ],
  female:[
    {id:'bob',label:'Tóc bob'},
    {id:'long',label:'Tóc dài'},
    {id:'pony',label:'Buộc cao'}
  ]
};
const AVATAR_V378_OUTFITS=[
  {id:'school-blue',label:'Đồng phục xanh',top:'#EAF2FF',accent:'#315BC7',bottom:'#27364E'},
  {id:'school-white',label:'Đồng phục trắng',top:'#FFFFFF',accent:'#64748B',bottom:'#334155'},
  {id:'sport-basic',label:'Thể thao cơ bản',top:'#E8F7EF',accent:'#27845A',bottom:'#1F4D3A'}
];
let avatarV378Draft=null;
let avatarV378OnboardingGender='';
let avatarV378PromptedUid='';

function avatarV378OwnerUid(){return firebaseUser?.uid||'local'}
function avatarV378Starter(gender='male'){
  return {schemaVersion:AVATAR_V378_SCHEMA,initialized:false,ownerUid:avatarV378OwnerUid(),gender:gender==='female'?'female':'male',skin:'warm',face:'smile',hair:gender==='female'?'bob':'short',outfit:'school-blue',level:AVATAR_V378_STARTER_LEVEL,rank:AVATAR_V378_RANK,starter:true,updatedAt:''};
}
function avatarV378Sanitize(raw,owner=avatarV378OwnerUid()){
  if(!raw||typeof raw!=='object')return null;
  let gender=raw.gender==='female'?'female':raw.gender==='male'?'male':'';
  if(!gender)return null;
  const hairs=AVATAR_V378_HAIR[gender].map(x=>x.id);
  return {
    schemaVersion:AVATAR_V378_SCHEMA,
    initialized:raw.initialized===true,
    ownerUid:owner,
    gender,
    skin:AVATAR_V378_SKINS[raw.skin]?raw.skin:'warm',
    face:AVATAR_V378_FACES[raw.face]?raw.face:'smile',
    hair:hairs.includes(raw.hair)?raw.hair:hairs[0],
    outfit:AVATAR_V378_OUTFITS.some(x=>x.id===raw.outfit)?raw.outfit:'school-blue',
    level:AVATAR_V378_STARTER_LEVEL,
    rank:AVATAR_V378_RANK,
    starter:true,
    updatedAt:String(raw.updatedAt||'')
  };
}
function avatarV378Stored(){
  const uid=avatarV378OwnerUid();
  let cloud=avatarV378Sanitize(firebaseProfile?.avatarV378,uid);
  if(cloud)return cloud;
  let local=avatarV378Sanitize(state?.avatarV378,uid);
  if(local&&String(state.avatarV378?.ownerUid||'')===uid)return local;
  return null;
}
function avatarV378Current(){return avatarV378Sanitize(avatarV378Draft)||avatarV378Stored()||avatarV378Starter(avatarV378OnboardingGender||'male')}
function avatarV378DisplayName(){return firebaseProfile?.displayName||firebaseUser?.displayName||firebaseUser?.email?.split('@')[0]||'Học sinh Math12'}
function avatarV378Outfit(id){return AVATAR_V378_OUTFITS.find(x=>x.id===id)||AVATAR_V378_OUTFITS[0]}

function avatarV378HairSvg(a){
  const hair='#253047',hi='#39445C';
  if(a.gender==='female'){
    if(a.hair==='long')return `<path d="M75 88 Q76 40 120 36 Q164 40 165 90 L160 184 Q148 198 137 187 L140 97 Q121 77 100 93 L103 188 Q91 200 80 184 Z" fill="${hair}"/><path d="M84 75 Q116 38 154 72 Q139 55 119 54 Q99 55 84 75Z" fill="${hi}" opacity=".65"/>`;
    if(a.hair==='pony')return `<path d="M78 89 Q76 42 119 36 Q161 40 162 87 L151 78 Q136 54 105 59 Q91 62 82 81Z" fill="${hair}"/><path d="M153 58 Q184 59 181 93 Q176 112 159 118 Q170 88 151 76Z" fill="${hair}"/><circle cx="156" cy="66" r="8" fill="#53617D"/>`;
    return `<path d="M76 91 Q76 42 120 36 Q164 41 165 91 L157 135 Q151 148 140 143 L142 92 Q120 73 98 91 L100 144 Q87 149 81 135Z" fill="${hair}"/><path d="M85 70 Q105 47 128 52 Q148 55 157 76 Q137 61 117 63 Q99 63 85 70Z" fill="${hi}" opacity=".55"/>`;
  }
  if(a.hair==='side')return `<path d="M78 88 Q79 43 121 38 Q160 40 162 83 Q148 62 128 58 Q104 53 82 82Z" fill="${hair}"/><path d="M91 58 Q123 38 153 61 Q122 55 99 70Z" fill="${hi}" opacity=".58"/>`;
  if(a.hair==='spiky')return `<path d="M79 85 L85 53 L98 61 L108 38 L120 54 L134 36 L139 57 L158 49 L162 86 Q142 61 120 60 Q96 60 79 85Z" fill="${hair}"/>`;
  return `<path d="M79 87 Q79 45 120 38 Q159 43 162 87 Q145 62 120 61 Q96 61 79 87Z" fill="${hair}"/><path d="M90 59 Q118 43 149 63 Q119 57 95 70Z" fill="${hi}" opacity=".48"/>`;
}
function avatarV378Svg(raw,size='large'){
  const a=avatarV378Sanitize(raw)||avatarV378Starter('male'),skin=AVATAR_V378_SKINS[a.skin],out=avatarV378Outfit(a.outfit);
  const cls=size==='mini'?'avatar-svg avatar-svg-mini':'avatar-svg';
  const smile=a.face==='smile'?`<path d="M108 112 Q120 121 132 112" fill="none" stroke="#7C443B" stroke-width="3.2" stroke-linecap="round"/>`:a.face==='confident'?`<path d="M108 114 Q120 121 133 111" fill="none" stroke="#7C443B" stroke-width="3" stroke-linecap="round"/>`:a.face==='focus'?`<path d="M110 116 Q120 113 130 116" fill="none" stroke="#7C443B" stroke-width="3" stroke-linecap="round"/>`:`<path d="M110 114 Q120 117 130 114" fill="none" stroke="#7C443B" stroke-width="3" stroke-linecap="round"/>`;
  const lower=a.gender==='female'?`<path d="M84 250 L156 250 L172 321 L68 321Z" fill="${out.bottom}"/><path d="M89 321 L111 321 L106 354 L82 354Z" fill="#E7EDF6"/><path d="M129 321 L151 321 L158 354 L134 354Z" fill="#E7EDF6"/>`:`<path d="M82 250 L158 250 L151 329 L126 329 L120 275 L114 329 L89 329Z" fill="${out.bottom}"/><path d="M89 329 L112 329 L108 354 L83 354Z" fill="#E7EDF6"/><path d="M127 329 L151 329 L158 354 L133 354Z" fill="#E7EDF6"/>`;
  return `<svg class="${cls}" viewBox="0 0 240 370" role="img" aria-label="Avatar ${a.gender==='female'?'nữ':'nam'} ${esc(AVATAR_V378_RANK)}" xmlns="http://www.w3.org/2000/svg">
    <defs><linearGradient id="avbg-${a.gender}-${a.skin}-${a.outfit}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#F6F9FF"/><stop offset="1" stop-color="#DDE8FF"/></linearGradient></defs>
    <rect x="8" y="8" width="224" height="354" rx="42" fill="url(#avbg-${a.gender}-${a.skin}-${a.outfit})"/>
    <circle cx="120" cy="105" r="46" fill="${skin.fill}"/><ellipse cx="76" cy="106" rx="7" ry="12" fill="${skin.shadow}" opacity=".8"/><ellipse cx="164" cy="106" rx="7" ry="12" fill="${skin.shadow}" opacity=".8"/>
    ${avatarV378HairSvg(a)}
    <ellipse cx="103" cy="102" rx="4.2" ry="5" fill="#263244"/><ellipse cx="137" cy="102" rx="4.2" ry="5" fill="#263244"/><path d="M102 91 Q108 87 113 91" fill="none" stroke="#6D4D43" stroke-width="2" stroke-linecap="round"/><path d="M128 91 Q134 87 140 91" fill="none" stroke="#6D4D43" stroke-width="2" stroke-linecap="round"/>${smile}
    <path d="M105 143 L105 161 Q120 172 135 161 L135 143" fill="${skin.fill}"/>
    <path d="M78 173 Q120 151 162 173 L171 252 L69 252Z" fill="${out.top}" stroke="#D8E1EF" stroke-width="2"/>
    <path d="M104 162 L120 181 L136 162" fill="#FFFFFF"/><path d="M120 181 L120 245" stroke="${out.accent}" stroke-width="8"/><path d="M82 180 Q60 202 60 245 L77 249 L91 194Z" fill="${out.top}"/><path d="M158 180 Q180 202 180 245 L163 249 L149 194Z" fill="${out.top}"/>
    <circle cx="69" cy="249" r="10" fill="${skin.fill}"/><circle cx="171" cy="249" r="10" fill="${skin.fill}"/>
    ${lower}
    <path d="M80 354 Q96 348 111 354 L110 361 L78 361Z" fill="#27364E"/><path d="M130 354 Q145 348 160 354 L162 361 L130 361Z" fill="#27364E"/>
    <circle cx="205" cy="46" r="20" fill="#FFFFFF" opacity=".92"/><text x="205" y="52" text-anchor="middle" font-size="17" font-weight="800" fill="#315BC7">1</text>
  </svg>`;
}
function avatarV378GenericSvg(size='mini'){
  const cls=size==='mini'?'avatar-svg avatar-svg-mini':'avatar-svg';
  return `<svg class="${cls}" viewBox="0 0 240 370" role="img" aria-label="Avatar chưa thiết lập" xmlns="http://www.w3.org/2000/svg"><rect x="8" y="8" width="224" height="354" rx="42" fill="#EEF3FB"/><circle cx="120" cy="105" r="46" fill="#D7DFEC"/><path d="M77 87 Q81 45 120 40 Q159 45 163 87 Q145 64 120 63 Q95 64 77 87Z" fill="#AAB6C9"/><path d="M72 176 Q120 148 168 176 L176 260 L64 260Z" fill="#DDE5F1"/><path d="M87 259 L113 259 L109 350 L83 350Z" fill="#C7D1E1"/><path d="M127 259 L153 259 L158 350 L132 350Z" fill="#C7D1E1"/><circle cx="205" cy="46" r="20" fill="#FFFFFF"/><text x="205" y="52" text-anchor="middle" font-size="17" font-weight="800" fill="#8A99B1">?</text></svg>`;
}
function avatarV378MiniHtml(a){return `<span class="avatar-v378-mini">${a?avatarV378Svg(a,'mini'):avatarV378GenericSvg('mini')}</span>`}

function avatarV378NotifyChanged(field,value){
  const detail={field,value,avatar:avatarV378Draft?{...avatarV378Draft}:avatarV378Current(),at:Date.now()};
  requestAnimationFrame(()=>{
    try{window.dispatchEvent(new CustomEvent('math12hub:avatar-changed',{detail}))}catch(_){}
    try{window.v384Avatar3D?.rebuild?.()}catch(_){}
  });
}
function avatarV378Set(field,value){
  let a=avatarV378Current();
  if(field==='gender'){
    const gender=value==='female'?'female':'male';a.gender=gender;a.hair=gender==='female'?'bob':'short';
  }else if(field==='skin'&&AVATAR_V378_SKINS[value])a.skin=value;
  else if(field==='face'&&AVATAR_V378_FACES[value])a.face=value;
  else if(field==='hair'&&AVATAR_V378_HAIR[a.gender].some(x=>x.id===value))a.hair=value;
  else if(field==='outfit'&&AVATAR_V378_OUTFITS.some(x=>x.id===value))a.outfit=value;
  avatarV378Draft={...a,ownerUid:avatarV378OwnerUid(),updatedAt:new Date().toISOString()};
  // : keep the starter editor and the layered wardrobe in sync.
  // Without this, the wardrobe's starter slots can override the newly selected hair/outfit.
  try{window.v385Wardrobe?.syncBase?.(field,avatarV378Draft)}catch(_){}
  avatarV378RenderPage();
  avatarV378NotifyChanged(field,value);
}
function avatarV378OptionButton(field,id,label,current,extra=''){
  return `<button class="avatar-choice ${current===id?'selected':''}" type="button" onclick="avatarV378Set('${field}','${id}')"><span>${extra||label}</span><small>${esc(label)}</small><em>Miễn phí</em></button>`;
}
function avatarV378RenderPage(){
  const root=document.getElementById('avatarV378Page');if(!root)return;
  const a=avatarV378Current(),stored=avatarV378Stored(),isSaved=!!stored?.initialized&&!avatarV378Draft;
  const hair=AVATAR_V378_HAIR[a.gender];
  root.innerHTML=`<div class="avatar-page-grid">
    <section class="card avatar-preview-card">
      <div class="avatar-preview-kicker">NHÂN VẬT HỌC TẬP</div>
      <div class="avatar-preview-stage">${avatarV378Svg(a)}</div>
      <div class="avatar-name">${esc(avatarV378DisplayName())}</div>
      <div class="avatar-rank-row"><span>Lv.${AVATAR_V378_STARTER_LEVEL}</span><b>${esc(AVATAR_V378_RANK)}</b></div>
      <p>Nhân vật khởi đầu dùng vật phẩm cơ bản; EXP, vàng và Shop được đồng bộ cùng hồ sơ học tập.</p>
      <div class="avatar-foundation-status"><span>✓ Avatar cá nhân</span><span>✓ Đồng bộ tài khoản</span><span>✓ Bộ đồ tân thủ</span></div>
    </section>
    <section class="card avatar-builder-card">
      <div class="section-head avatar-builder-head"><div><h3>Tạo nhân vật tân thủ</h3><p>Chọn diện mạo cơ bản. Các lựa chọn tân thủ đều miễn phí.</p></div><span class="avatar-save-state ${isSaved?'saved':'draft'}">${isSaved?'Đã lưu':'Đang chỉnh'}</span></div>
      <div class="avatar-builder-section"><label>1. Kiểu nhân vật</label><div class="avatar-gender-grid">
        <button class="avatar-gender-card ${a.gender==='male'?'selected':''}" onclick="avatarV378Set('gender','male')" type="button">${avatarV378Svg({...a,gender:'male',hair:'short'},'mini')}<b>Nam</b><small>Tân thủ nam</small></button>
        <button class="avatar-gender-card ${a.gender==='female'?'selected':''}" onclick="avatarV378Set('gender','female')" type="button">${avatarV378Svg({...a,gender:'female',hair:'bob'},'mini')}<b>Nữ</b><small>Tân thủ nữ</small></button>
      </div></div>
      <div class="avatar-builder-section"><label>2. Tông da</label><div class="avatar-choice-grid avatar-skin-grid">${Object.entries(AVATAR_V378_SKINS).map(([id,x])=>avatarV378OptionButton('skin',id,x.label,a.skin,`<i style="background:${x.fill}"></i>`)).join('')}</div></div>
      <div class="avatar-builder-section"><label>3. Gương mặt</label><div class="avatar-choice-grid">${Object.entries(AVATAR_V378_FACES).map(([id,x])=>avatarV378OptionButton('face',id,x.label,a.face,id==='smile'?'☺':id==='confident'?'◕‿◕':id==='focus'?'⌁':'—')).join('')}</div></div>
      <div class="avatar-builder-section"><label>4. Kiểu tóc</label><div class="avatar-choice-grid">${hair.map(x=>avatarV378OptionButton('hair',x.id,x.label,a.hair,'✦')).join('')}</div></div>
      <div class="avatar-builder-section"><label>5. Trang phục tân thủ</label><div class="avatar-outfit-grid">${AVATAR_V378_OUTFITS.map(x=>`<button class="avatar-outfit-card ${a.outfit===x.id?'selected':''}" type="button" onclick="avatarV378Set('outfit','${x.id}')"><span class="avatar-outfit-swatch"><i style="background:${x.top}"></i><i style="background:${x.accent}"></i><i style="background:${x.bottom}"></i></span><b>${esc(x.label)}</b><small>Starter • 0 vàng</small></button>`).join('')}</div></div>
      <div class="avatar-builder-actions"><button class="btn btn-soft" type="button" onclick="avatarV378ResetDraft()">Đặt lại</button><button class="btn btn-blue" type="button" onclick="avatarV378Save()">${stored?.initialized?'Lưu thay đổi':'Hoàn tất nhân vật'}</button></div>
    </section>
  </div>
  <div class="avatar-future-grid mt">
    <div class="card avatar-future-card"><span>⚡</span><div><b>EXP & Level</b><small>Tăng theo hoạt động học tập.</small></div><em>Đang dùng</em></div>
    <div class="card avatar-future-card"><span>🪙</span><div><b>Vàng</b><small>Dùng cho vật phẩm thẩm mỹ.</small></div><em>Đang dùng</em></div>
    <div class="card avatar-future-card"><span>🛍</span><div><b>Shop & Inventory</b><small>Quản lý vật phẩm và trang phục đã sở hữu.</small></div><em>Đang dùng</em></div>
  </div>`;
}
function avatarV378ResetDraft(){avatarV378Draft=avatarV378Stored()||avatarV378Starter(avatarV378Current().gender);try{window.v385Wardrobe?.syncBase?.('reset',avatarV378Draft)}catch(_){}avatarV378RenderPage();avatarV378NotifyChanged('reset','')}
async function avatarV378Save(){
  let a=avatarV378Current();a={...a,initialized:true,ownerUid:avatarV378OwnerUid(),updatedAt:new Date().toISOString()};
  state.avatarV378=a;avatarV378Draft=null;save({sync:false,reason:'avatar-v37.8'});
  if(firebaseUser&&firebaseDb&&!firebaseAccountLocked){
    try{await firebaseDb.collection('users').doc(firebaseUser.uid).set({avatarV378:a,updatedAt:firebaseServerTimestamp()},{merge:true});firebaseProfile={...(firebaseProfile||{}),avatarV378:a};firebaseAuditLog?.('profile.avatar.update',{gender:a.gender,hair:a.hair,outfit:a.outfit}).catch?.(()=>{});examToast?.('✓ Đã lưu nhân vật tân thủ');}
    catch(err){console.warn('Avatar  cloud save',err);examToast?.('Đã lưu trên máy; chưa đồng bộ được avatar.')}
  }else examToast?.('Đã lưu avatar trên thiết bị. Đăng nhập để đồng bộ.');
  avatarV378RefreshUI();avatarV378RenderPage();
}
