function v29CsvCell(v){return `"${String(v??'').replaceAll('"','""')}"`}
function exportQuestionBankCSVV29(){
  if(!requireTeacher('Xuất CSV ngân hàng'))return;const rows=v29FilteredQuestions().map(q=>window.ID6V374?.normalizeQuestion?.(q)||q),head=['questionId','id','id6','id6Pattern','chapterId','lessonId','knowledgeCode','level','type','difficulty','reviewStatus','sourceName','sourceYear','tags','question','answer','explanation','version'];let csv='\uFEFF'+head.map(v29CsvCell).join(',')+'\n'+rows.map(q=>head.map(k=>{let v=q[k];if(k==='tags')v=(q.tags||[]).join('; ');if(k==='answer'&&q.type==='tf4')v=(q.statements||[]).map(s=>s.answer?'Đ':'S').join('');if(k==='answer'&&q.type==='mcq')v=String.fromCharCode(65+(Number(q.answer)||0));return v29CsvCell(v)}).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`math12-question-bank-v29-${rows.length}-cau.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)
}
function v29QuestionToLatex(q={}){
  q=window.ID6V374?.normalizeQuestion?.(q)||q;
  const meta=[`% questionId: ${q.questionId||''}`,q.id6?`% id6: ${q.id6}`:'',`% id: ${q.id}`,`% lesson: ${q.lessonId}`,`% knowledge: ${q.knowledgeCode}`,`% level: ${q.level}`,q.form?`% form: ${q.form}`:'',q.sourceName?`% source: ${q.sourceName}`:'',q.sourceYear?`% year: ${q.sourceYear}`:'',q.tags?.length?`% tags: ${q.tags.join(', ')}`:''].filter(Boolean).join('\n');
  let stem=q.question||'',body='';if(q.figureLatex&&q.figureLayout==='right')stem=`\\immini{${stem}}{${q.figureLatex}}`;else if(q.figureLatex&&q.figureLayout==='left')stem=`\\imminiL{${stem}}{${q.figureLatex}}`;else if(q.figureLatex)stem+=`\n${q.figureLatex}`;
  if(q.type==='mcq')body=`\\choice\n${(q.options||[]).map((o,i)=>`{${Number(q.answer)===i?'\\True ':''}${o}}`).join('\n')}`;
  else if(q.type==='tf4')body=`\\choiceTF\n${(q.statements||[]).map(s=>`{${s.answer?'\\True ':''}${s.text||''}}`).join('\n')}`;
  else if(q.type==='tf')body=`\\choiceTF\n{${q.answer?'\\True ':''}${q.question||''}}`; // legacy 1-statement TF: preserve source, never fabricate extra statements
  else body=`\\shortans{${q.answer??''}}`;
  const solution=q.explanation?`\n\\loigiai{${q.explanation}}`:'';return `${meta}\n\\begin{ex}\n${stem}\n${body}${solution}\n\\end{ex}`;
}
function exportQuestionBankLatexV29(){
  if(!requireTeacher('Xuất LaTeX ngân hàng'))return;const rows=v29FilteredQuestions();let tex=`% Math12 Hub  — export ${rows.length} câu\n% ${new Date().toISOString()}\n\n`+rows.map(v29QuestionToLatex).join('\n\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([tex],{type:'text/plain;charset=utf-8'}));a.download=`math12-question-bank-v29-${rows.length}-cau.tex`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)
}
function v29InjectEditorMetadata(id=''){
  const grid=document.querySelector('#modalBody .field-grid');if(!grid||document.getElementById('qeReviewStatus'))return;const x=id?(state.questionBank||[]).find(q=>q.id===id):null,anchor=document.getElementById('qeQuestion')?.closest('.field');if(!anchor)return;
  const wrap=document.createElement('div');wrap.className='v29-editor-meta full';wrap.innerHTML=`<div class="v29-editor-meta-head"><b>Metadata Question Bank Pro</b><span>${x?`v${Number(x.version)||1}`:'Câu mới'}</span></div><div class="qid-editor-row"><div><small>ID câu cố định</small><b>${esc(x?.questionId||'Sẽ tự cấp khi lưu')}</b></div>${x?.questionId?`<button type="button" class="btn btn-soft" onclick="QuestionIdV40.copy('${attrEsc(x.questionId)}')">Sao chép ID</button>`:''}</div><div class="field-grid"><div class="field"><label>Trạng thái duyệt</label><select id="qeReviewStatus"><option value="draft" ${(x?.reviewStatus||'draft')==='draft'?'selected':''}>Bản nháp</option><option value="reviewed" ${x?.reviewStatus==='reviewed'?'selected':''}>Đã duyệt chuyên môn</option><option value="approved" ${x?.reviewStatus==='approved'?'selected':''}>Approved • sẵn sàng sử dụng</option></select></div><div class="field"><label>Độ khó 1–5</label><select id="qeDifficulty">${[1,2,3,4,5].map(n=>`<option value="${n}" ${Number(x?.difficulty||v29DefaultDifficulty(x?.level))===n?'selected':''}>${n}/5</option>`).join('')}</select></div><div class="field"><label>Nguồn / tài liệu</label><input id="qeSourceName" value="${attrEsc(x?.sourceName||'')}" placeholder="VD: Đề TN THPT 2026"></div><div class="field"><label>Năm nguồn</label><input id="qeSourceYear" inputmode="numeric" maxlength="4" value="${attrEsc(x?.sourceYear||'')}" placeholder="2026"></div><div class="field full"><label>Thẻ tìm kiếm</label><input id="qeTags" value="${attrEsc((x?.tags||[]).join(', '))}" placeholder="VD: cực trị, bảng biến thiên, thực tế"><div class="math-help">Phân cách thẻ bằng dấu phẩy; tối đa 12 thẻ. Metadata được đồng bộ cùng document câu hỏi.</div></div></div>`;
  anchor.insertAdjacentElement('beforebegin',wrap)
}
function v29ReadEditorMeta(){return {reviewStatus:document.getElementById('qeReviewStatus')?.value||'draft',difficulty:Number(document.getElementById('qeDifficulty')?.value)||3,sourceName:(document.getElementById('qeSourceName')?.value||'').trim(),sourceYear:(document.getElementById('qeSourceYear')?.value||'').replace(/[^0-9]/g,'').slice(0,4),tags:v29NormalizeTags(document.getElementById('qeTags')?.value||'')}}

// Wrap the  editor without duplicating the mature LaTeX/figure validation logic.
const v29BaseOpenQuestionEditor=openQuestionEditor;
openQuestionEditor=function(id=''){v29BaseOpenQuestionEditor(id);v29InjectEditorMetadata(id)};
const v29BaseSaveQuestionEditor=saveQuestionEditor;
saveQuestionEditor=function(editId=''){
  const old=editId?v29Clone((state.questionBank||[]).find(q=>q.id===editId)||null):null,meta=v29ReadEditorMeta(),typedId=(document.getElementById('qeId')?.value||'').trim().replace(/[^A-Za-z0-9._-]/g,'-'),beforeRev=Number(state._meta?.revision)||0;
  v29BaseSaveQuestionEditor(editId);if((Number(state._meta?.revision)||0)<=beforeRev)return;
  const targetId=typedId||editId;let idx=targetId?(state.questionBank||[]).findIndex(q=>q.id===targetId):-1;if(idx<0&&!editId)idx=0;if(idx<0)return;
  const current=state.questionBank[idx],history=old?v29TrimVersions([...(old._versions||[]),v29VersionSnapshot(old)]):[];
  state.questionBank[idx]=v29NormalizeQuestion({...current,...meta,questionId:old?.questionId||current.questionId||'',source:current.source||'custom',createdAt:old?.createdAt||current.createdAt||v29IsoNow(),updatedAt:v29IsoNow(),version:old?(Number(old.version)||1)+1:(Number(current.version)||1),_versions:history});
  save({reason:old?'v29-question-edit':'v29-question-create'});v29DuplicateCache.signature='';renderQuestionBank(true)
};
const v29BaseCommitBulkLatexImport=commitBulkLatexImport;
commitBulkLatexImport=function(){const beforeRev=Number(state._meta?.revision)||0,beforeMap=new Map((state.questionBank||[]).map(q=>[q.id,v29Clone(q)]));v29BaseCommitBulkLatexImport();if((Number(state._meta?.revision)||0)>beforeRev){(state.questionBank||[]).forEach(q=>{const old=beforeMap.get(q.id);if(old?.questionId)q.questionId=old.questionId});window.QuestionIdV40?.ensureBank?.(state.questionBank,{saveChanges:false});v29EnsureQuestionBankMetadata(false);(state.questionBank||[]).forEach(q=>{const old=beforeMap.get(q.id);if(q.source==='latex-import'&&!q.updatedAt)q.updatedAt=v29IsoNow();if(old&&JSON.stringify(v29StripVersions(old))!==JSON.stringify(v29StripVersions(q))){q._versions=v29TrimVersions([...(old._versions||[]),v29VersionSnapshot(old)]);q.version=(Number(old.version)||1)+1;q.createdAt=old.createdAt||q.createdAt||'';q.updatedAt=v29IsoNow()}});save({reason:'v29-latex-import-metadata'});v29DuplicateCache.signature='';renderQuestionBank(true)}};
const v29BaseDeleteBankQuestion=deleteBankQuestion;
deleteBankQuestion=async function(id){await v29BaseDeleteBankQuestion(id);v29DuplicateCache.signature='';renderQuestionBank(true)};
renderQuestionBank=v29RenderQuestionBank;

function v29BankChangePage(delta=0){v29BankPage=Math.max(1,v29BankPage+Number(delta||0));renderQuestionBank()}
function v29BindBankControls(){['bankReviewStatus','bankDifficulty','bankSource','bankSort','bankPageSize'].forEach(id=>document.getElementById(id)?.addEventListener('change',()=>renderQuestionBank()));const dup=document.getElementById('bankDuplicateFilter');dup?.addEventListener('change',()=>{if(dup.value)v29ScanDuplicates(true);renderQuestionBank()});document.getElementById('bankTag')?.addEventListener('input',()=>v34ScheduleBankRender(false))}
v29EnsureQuestionBankMetadata(true);v29BindBankControls();


/* ===== assets/js/exam-pro-v30.js ===== */
/* =========================  • EXAM ENGINE PRO =========================
   - Multiple deterministic exam codes without duplicating the question bank
   - Controlled question / MCQ option shuffling
   - Assignment reveal policy
   - Cloud draft autosave for secure assignments
   - Variant-aware grading while keeping Secure Exam  + Low Reads 
*/
const V30_EXAM_SCHEMA=30;
const V30_VARIANT_CODES=['A','B','C','D','E','F','G','H'];
let v30CloudDraftTimer=null,v30CloudDraftLastWrite=0,v30CloudDraftHash='';

function v30Int(v,min=0,max=999){return Math.min(max,Math.max(min,parseInt(v,10)||0))}
function v30PolicyDefaults(){return {variantCount:1,shuffleQuestions:true,shuffleOptions:true,revealPolicy:'after_due',preserveSections:true}}
function v30NormalizePolicy(p={}){let d=v30PolicyDefaults(),r={...d,...(p||{})};r.variantCount=v30Int(r.variantCount,1,8);r.shuffleQuestions=r.shuffleQuestions!==false;r.shuffleOptions=r.shuffleOptions!==false;r.preserveSections=r.preserveSections!==false;r.revealPolicy=['never','after_due','after_grade'].includes(r.revealPolicy)?r.revealPolicy:'after_due';return r}
function v30PolicyFromBuilder(){return v30NormalizePolicy({variantCount:document.getElementById('ebV30VariantCount')?.value||1,shuffleQuestions:!!document.getElementById('ebV30ShuffleQuestions')?.checked,shuffleOptions:!!document.getElementById('ebV30ShuffleOptions')?.checked,preserveSections:!!document.getElementById('ebV30PreserveSections')?.checked,revealPolicy:document.getElementById('ebV30RevealPolicy')?.value||'after_due'})}
function v30RefreshBuilderPolicy(){if(typeof examBuilderDraft!=='undefined'&&examBuilderDraft){examBuilderDraft.v30Policy=v30PolicyFromBuilder();examBuilderDraft.variantCount=examBuilderDraft.v30Policy.variantCount;examBuilderDraft.schemaVersion=30}if(typeof updateExamBuilderSummary==='function')updateExamBuilderSummary();if(typeof renderExamBuilderPreview==='function'&&typeof examBuilderDraft!=='undefined'&&examBuilderDraft)renderExamBuilderPreview()}
function v30PolicyFromExam(e={}){let hasV30=!!e.v30Policy||e.v30ExamEngine===true||e.schemaVersion===30||e.variantCount!=null||e.shuffleQuestions!=null||e.shuffleOptions!=null||e.revealPolicy!=null;if(!hasV30)return {variantCount:1,shuffleQuestions:false,shuffleOptions:false,preserveSections:true,revealPolicy:'never'};return v30NormalizePolicy(e.v30Policy||{variantCount:e.variantCount,shuffleQuestions:e.shuffleQuestions,shuffleOptions:e.shuffleOptions,preserveSections:e.preserveSections,revealPolicy:e.revealPolicy})}
function v30VariantCode(i=0){return V30_VARIANT_CODES[v30Int(i,0,7)]||String(i+1)}
function v30Hash(text=''){return typeof examSeedFromText==='function'?examSeedFromText(String(text)):String(text).split('').reduce((h,c)=>((h*31+c.charCodeAt(0))>>>0),2166136261)}
function v30VariantIndex(a={},uid='',attemptNumber=1){let p=v30NormalizePolicy(a.v30Policy||a),n=p.variantCount;if(n<=1)return 0;return (v30Hash(`${uid}|${a.id||a.assignmentId||a.sourceExamId||''}`)+Math.max(0,(Number(attemptNumber)||1)-1))%n}
function v30Permutation(n,seed){return examShuffle(Array.from({length:n},(_,i)=>i),seed)}
function v30ShuffleQuestionOptions(q,seed){let x=firebaseSafeClone?firebaseSafeClone(q):JSON.parse(JSON.stringify(q));if(x.type!=='mcq'||!Array.isArray(x.options)||x.options.length<2)return x;let perm=v30Permutation(x.options.length,seed),old=x.options.slice(),oldAnswer=Number(x.answer);x.options=perm.map(i=>old[i]);if(Number.isInteger(oldAnswer)&&oldAnswer>=0&&oldAnswer<old.length)x.answer=perm.indexOf(oldAnswer);x.v30OptionOrder=perm;return x}
function v30ApplyVariant(questions=[],policy={},variantIndex=0,context='exam'){
  let p=v30NormalizePolicy(policy),seed=v30Hash(`${context}|variant:${variantIndex}|v30`),qs=(questions||[]).map((q,i)=>p.shuffleOptions?v30ShuffleQuestionOptions(q,v30Hash(`${seed}|${q.id||i}|options`)):(firebaseSafeClone?firebaseSafeClone(q):JSON.parse(JSON.stringify(q))));
  if(p.shuffleQuestions){
    const hasSections=p.preserveSections&&qs.some(q=>q.section);
    if(hasSections){let order=['I','II','III'],seen=new Set(order),groups=[];order.forEach(s=>{let g=qs.filter(q=>q.section===s);if(g.length)groups.push(examShuffle(g,v30Hash(`${seed}|section:${s}`)))});let rest=qs.filter(q=>!seen.has(q.section));if(rest.length)groups.push(examShuffle(rest,v30Hash(`${seed}|section:rest`)));qs=groups.flat()}
    else qs=examShuffle(qs,seed);
  }
  return qs.map((q,i)=>({...q,v30DisplayNo:i+1}));
}
function v30VariantMeta(policy,index){let p=v30NormalizePolicy(policy);return {variantIndex:index,variantCode:v30VariantCode(index),variantCount:p.variantCount,shuffleQuestions:p.shuffleQuestions,shuffleOptions:p.shuffleOptions,preserveSections:p.preserveSections}}
function v30RevealLabel(v){return ({never:'Không công bố đáp án',after_due:'Sau khi hết hạn',after_grade:'Sau khi giáo viên chấm'})[v]||'Sau khi hết hạn'}

/* ---------- Exam builder ---------- */
const v30OldGenerateExamBuilderDraft=generateExamBuilderDraft;
generateExamBuilderDraft=function(){v30OldGenerateExamBuilderDraft();if(examBuilderDraft){examBuilderDraft.v30Policy=v30PolicyFromBuilder();examBuilderDraft.variantCount=examBuilderDraft.v30Policy.variantCount;examBuilderDraft.schemaVersion=30;renderExamBuilderPreview()}}
const v30OldSaveExamBuilderDraft=saveExamBuilderDraft;
saveExamBuilderDraft=function(){if(examBuilderDraft){examBuilderDraft.v30Policy=v30PolicyFromBuilder();examBuilderDraft.variantCount=examBuilderDraft.v30Policy.variantCount;examBuilderDraft.schemaVersion=30}return v30OldSaveExamBuilderDraft()}
const v30OldExamBuilderPreset=examBuilderPreset;
examBuilderPreset=function(kind,silent=false){let r=v30OldExamBuilderPreset(kind,silent);let count=document.getElementById('ebV30VariantCount');if(count)count.value=kind==='thpt'||kind==='final'?4:kind==='periodic'?2:1;let preserve=document.getElementById('ebV30PreserveSections');if(preserve)preserve.checked=true;let reveal=document.getElementById('ebV30RevealPolicy');if(reveal)reveal.value='after_due';return r}
examBuilderConfig=function(exam,variantIndex=0){let p=v30PolicyFromExam(exam),i=v30Int(variantIndex,0,p.variantCount-1),q=v30ApplyVariant(exam.questions||[],p,i,`local:${exam.id||exam.title}`),meta=v30VariantMeta(p,i);return {id:`custom-${exam.id}-v${i}`,mode:'custom',title:exam.title,subtitle:`${q.length} câu • ${exam.durationMinutes} phút • Mã ${meta.variantCode}/${p.variantCount}`,durationMinutes:exam.durationMinutes,questions:q,scoring:exam.scoring||'normalized',attemptType:`custom-${exam.id}-v${i}`,variantIndex:i,variantCode:meta.variantCode,v30Policy:p,rules:(exam.scoring==='thpt'?'Cấu trúc 12 câu nhiều lựa chọn, 4 câu Đúng/Sai 4 ý, 6 câu trả lời ngắn. Chấm theo thang THPT. ':'')+`Mã ${meta.variantCode}: ${p.shuffleQuestions?'đảo câu':'giữ thứ tự câu'}, ${p.shuffleOptions?'đảo phương án MCQ':'giữ phương án'}.`}}
startExamBuilderDraft=function(variantIndex=0){if(!examBuilderDraft){alert('Chưa có đề xem trước.');return}openExamStart(examBuilderConfig(examBuilderDraft,variantIndex))}
openSavedCustomExam=function(id,variantIndex=0){let e=(state.customExams||[]).find(x=>x.id===id);if(e)openExamStart(examBuilderConfig(e,variantIndex))}
const v30OldRenderExamBuilderPreview=renderExamBuilderPreview;
renderExamBuilderPreview=function(){v30OldRenderExamBuilderPreview();let box=document.getElementById('examBuilderPreview');if(!box||!examBuilderDraft)return;let p=v30PolicyFromExam(examBuilderDraft),head=box.querySelector('.exam-preview-head');if(head&&!box.querySelector('.v30-policy-strip')){let div=document.createElement('div');div.className='v30-policy-strip';div.innerHTML=`<div><b>${p.variantCount} mã đề</b><span>${p.shuffleQuestions?'Đảo câu':'Giữ câu'} • ${p.shuffleOptions?'Đảo phương án MCQ':'Giữ phương án'} • ${esc(v30RevealLabel(p.revealPolicy))}</span></div><div class="v30-code-actions">${Array.from({length:p.variantCount},(_,i)=>`<button class="btn btn-soft" onclick="startExamBuilderDraft(${i})">Thi mã ${v30VariantCode(i)}</button>`).join('')}</div>`;head.insertAdjacentElement('afterend',div)}}
renderSavedCustomExams=function(){let box=document.getElementById('examBuilderSaved');if(!box)return;let arr=state.customExams||[];box.innerHTML=arr.length?arr.map(e=>{let p=v30PolicyFromExam(e);return `<div class="saved-exam"><div><h4>${esc(e.title)}</h4><p>${e.questions?.length||0} câu • ${e.durationMinutes||45} phút • ${new Date(e.createdAt||Date.now()).toLocaleString('vi-VN')}${e.scoring==='thpt'?'thang THPT':''}</p><div class="v30-saved-meta"><span>${p.variantCount} mã</span><span>${p.shuffleQuestions?'đảo câu':'giữ câu'}</span><span>${p.shuffleOptions?'đảo MCQ':'giữ MCQ'}</span><span>${esc(v30RevealLabel(p.revealPolicy))}</span></div></div><div class="saved-exam-actions"><button class="btn btn-blue" onclick="openSavedCustomExam('${attrEsc(e.id)}',0)">Thi mã A</button><button class="btn btn-soft" onclick="previewSavedCustomExam('${attrEsc(e.id)}')">Xem</button><button class="btn btn-soft" onclick="exportCustomExam('${attrEsc(e.id)}')">JSON</button><button class="btn btn-danger" onclick="deleteSavedCustomExam('${attrEsc(e.id)}')">Xóa</button></div></div>`}).join(''):'<div class="exam-preview-empty" style="padding:18px">Chưa có đề tự tạo nào được lưu.</div>'}

/* ---------- Assignment UI / creation ---------- */
const v30OldRenderTeacherAssignments=firebaseRenderTeacherAssignments;
firebaseRenderTeacherAssignments=async function(classId,className='Lớp học'){
  await v30OldRenderTeacherAssignments(classId,className);let box=document.getElementById('onlineAssignments');if(!box)return;let form=box.querySelector('.assignment-create');if(form&&!document.getElementById('fbAssignmentVariantCount')){let exam=(state.customExams||[])[0],p=v30PolicyFromExam(exam||{}),wrap=document.createElement('div');wrap.className='full v30-assignment-policy';wrap.innerHTML=`<div class="v30-assignment-policy-grid"><div><label>Số mã đề</label><select id="fbAssignmentVariantCount">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${(i+1)===p.variantCount?'selected':''}>${i+1} mã</option>`).join('')}</select></div><div><label>Công bố đáp án</label><select id="fbAssignmentRevealPolicy"><option value="never">Không công bố</option><option value="after_due" ${p.revealPolicy==='after_due'?'selected':''}>Sau khi hết hạn</option><option value="after_grade" ${p.revealPolicy==='after_grade'?'selected':''}>Sau khi giáo viên chấm</option></select></div><label class="v30-check"><input id="fbAssignmentShuffleQuestions" type="checkbox" ${p.shuffleQuestions?'checked':''}> Đảo câu</label><label class="v30-check"><input id="fbAssignmentShuffleOptions" type="checkbox" ${p.shuffleOptions?'checked':''}> Đảo phương án MCQ</label></div><div class="smart-target-note"><b>:</b> mỗi học sinh/lượt làm được gán một mã ổn định; đề gốc chỉ lưu một lần. Đảo câu THPT giữ nguyên ba phần.</div>`;let note=form.querySelector('#fbSmartTargetNote')?.parentElement;note?form.insertBefore(wrap,note):form.appendChild(wrap)}
  let examSel=document.getElementById('fbAssignmentExam');if(examSel&&!examSel.dataset.v30Bound){examSel.dataset.v30Bound='1';examSel.addEventListener('change',()=>{let e=(state.customExams||[]).find(x=>x.id===examSel.value),p=v30PolicyFromExam(e||{});let n=document.getElementById('fbAssignmentVariantCount'),rq=document.getElementById('fbAssignmentShuffleQuestions'),ro=document.getElementById('fbAssignmentShuffleOptions'),rp=document.getElementById('fbAssignmentRevealPolicy');if(n)n.value=String(p.variantCount);if(rq)rq.checked=p.shuffleQuestions;if(ro)ro.checked=p.shuffleOptions;if(rp)rp.value=p.revealPolicy})}
  let banner=box.querySelector('.v27-assignment-create .firebase-banner');if(banner)banner.innerHTML='<b> Tạo nhiều mã đề + 🔒 Secure Exam + ⚡ Low Reads</b>Mã đề A–H, đảo câu/phương án có kiểm soát, cloud autosave và chính sách công bố đáp án.';
  box.querySelectorAll('.secure-chip').forEach(x=>{if(x.textContent.includes(''))x.textContent='🔒 '});let btn=[...box.querySelectorAll('button')].find(x=>x.textContent.includes('Giao bài '));if(btn)btn.textContent='＋ Giao bài ';
  try{let rows=await firebaseV19LoadAssignments(classId,false),cards=[...box.querySelectorAll('.assignment-card')].filter(x=>!x.classList.contains('v27-assignment-create'));cards.forEach((card,i)=>{let a=rows[i]?.data;if(!a)return;let meta=card.querySelector('.assignment-meta');if(meta&&!meta.querySelector('.v30-variant-badge')){let p=v30PolicyFromExam(a),span=document.createElement('span');span.className='v30-variant-badge';span.textContent=`${p.variantCount} mã • ${v30RevealLabel(p.revealPolicy)}`;meta.appendChild(span)}})}catch(_){}
}
