v22ClassSummary=function(c){let base=v31OldClassSummary?v31OldClassSummary(c):{},comp=c?.verifiedCompetencyV31||{},tested=v31CodeRows(c).filter(x=>x.attempts>=2),top=tested.filter(x=>x.accuracy<.8).sort((a,b)=>(a.accuracy??1)-(b.accuracy??1)||b.attempts-a.attempts)[0];return {...base,schemaVersion:31,verifiedEvidence:Number(comp.totalAttempts)||0,verifiedAccuracy:comp.accuracy==null?null:+Number(comp.accuracy).toFixed(4),verifiedCoverage:tested.length,weakVerifiedCode:top?.code||'',weakVerifiedAccuracy:top?.accuracy==null?null:+Number(top.accuracy).toFixed(4),capturedAt:new Date().toISOString()}};
v22PersistClassSummary=async function(c){if(!firebaseUser||!firebaseDb||!isTeacherRole?.()||!c?.classId)return;let summary=v22ClassSummary(c),owned=(firebaseOwnedClasses||[]).find(x=>x.id===c.classId),old=owned?.analyticsV31||owned?.analyticsV30||owned?.analyticsV29||owned?.analyticsV28||owned?.analyticsV27||owned?.analyticsV26||owned?.analyticsV25||owned?.analyticsV24||owned?.analyticsV23||owned?.analyticsV22||null,signature=JSON.stringify({m:summary.memberCount,a:summary.assignmentCount,c:summary.completionRate,s:summary.averageScore,h:summary.needsHelp,ve:summary.verifiedEvidence,va:summary.verifiedAccuracy,vc:summary.verifiedCoverage,w:summary.weakVerifiedCode}),oldSig=old?JSON.stringify({m:old.memberCount,a:old.assignmentCount,c:old.completionRate,s:old.averageScore,h:old.needsHelp,ve:old.verifiedEvidence,va:old.verifiedAccuracy,vc:old.verifiedCoverage,w:old.weakVerifiedCode}):'';if(old&&oldSig===signature)return;let now=Date.now(),last=v22SummaryWriteAt.get(c.classId)||0;if(now-last<V22_CLASS_SUMMARY_MIN_WRITE_MS)return;v22SummaryWriteAt.set(c.classId,now);try{await firebaseDb.collection('classes').doc(c.classId).set({analyticsV31:{...summary,updatedAt:firebaseServerTimestamp()}},{merge:true});if(owned)owned.analyticsV31=summary;v22RenderClassComparison(c)}catch(err){console.warn(' class summary',err)}};
v22RenderClassComparison=function(c){let box=document.getElementById('v22ClassComparison');if(!box)return;let rows=(firebaseOwnedClasses||[]).map(cls=>{let summary=cls.id===c.classId?v22ClassSummary(c):cls.analyticsV31||cls.analyticsV30||cls.analyticsV29||cls.analyticsV28||cls.analyticsV27||cls.analyticsV26||cls.analyticsV25||cls.analyticsV24||cls.analyticsV23||cls.analyticsV22||null;return {id:cls.id,name:cls.name||'Lớp học',summary,current:cls.id===c.classId}}).sort((a,b)=>(b.summary?.averageScore??-1)-(a.summary?.averageScore??-1));box.innerHTML=rows.length?`<div class="v22-compare-table">${rows.map((x,i)=>`<div class="v22-compare-row ${x.current?'current':''}"><span>${i+1}</span><div><b>${esc(x.name)}</b><small>${x.summary?`${x.summary.memberCount||0} HS • nộp ${x.summary.completionRate==null?'—':Math.round(x.summary.completionRate*100)+'%'} • ${x.summary.verifiedEvidence||0} câu xác minh`:'Chưa có snapshot'}</small></div><strong>${x.summary?.averageScore==null?'—':Number(x.summary.averageScore).toFixed(2)}</strong><em>${x.summary?.verifiedAccuracy==null?'—':Math.round(Number(x.summary.verifiedAccuracy)*100)+'%'}</em></div>`).join('')}</div><div class="v22-data-note">Cột cuối: độ chính xác năng lực xác minh . Lớp khác chỉ đọc snapshot trên document lớp, không tải học sinh.</div>`:'<div class="teacher-live-empty">Chưa có lớp để so sánh.</div>'};

