  function xTick(x,label=fmt(x,2)){if(!(x>b.xMin+1e-9&&x<b.xMax-1e-9)||Math.abs(x)<1e-9)return;const px=X(x),aboveRoom=axisY>P.t+24,belowRoom=axisY<H-P.b-18,fy=fn(x),curveY=Number.isFinite(fy)?Y(fy):null;let preferAbove=aboveRoom;if(s.smartLabels!==false&&curveY!=null&&Math.abs(curveY-axisY)<28)preferAbove=curveY>=axisY?aboveRoom:!belowRoom;const cands=preferAbove?[{x:px,y:axisY-9,anchor:'middle',bias:0},{x:px,y:axisY+18,anchor:'middle',bias:3}]:[{x:px,y:axisY+18,anchor:'middle',bias:0},{x:px,y:axisY-9,anchor:'middle',bias:3}];parts.push(`<line x1="${px}" y1="${axisY-3.5}" x2="${px}" y2="${axisY+3.5}" stroke="#111827" stroke-width="1"/>`,placeLabel(label,cands,'font-size="12" font-weight="500" fill="#111827"'))}
  function yTick(y,label=fmt(y,2)){if(!(y>b.yMin+1e-9&&y<b.yMax-1e-9)||Math.abs(y)<1e-9)return;const py=Y(y),leftRoom=axisX>P.l+30,cands=leftRoom?[{x:axisX-9,y:py+4,anchor:'end'},{x:axisX+9,y:py+4,anchor:'start',bias:4}]:[{x:axisX+9,y:py+4,anchor:'start'},{x:axisX-9,y:py+4,anchor:'end',bias:4}];parts.push(`<line x1="${axisX-3.5}" y1="${py}" x2="${axisX+3.5}" y2="${py}" stroke="#111827" stroke-width="1"/>`,placeLabel(label,cands,'font-size="12" font-weight="500" fill="#111827"'))}
  if(s.showGrid!==false){for(let x=Math.ceil(b.xMin/xStep)*xStep;x<=b.xMax+1e-9;x+=xStep)xTick(x);for(let y=Math.ceil(b.yMin/yStep)*yStep;y<=b.yMax+1e-9;y+=yStep)yTick(y)}
  else if(s.examStyle!==false){const sx=[...a.extrema.map(p=>p.x),...a.vertical];if(s.showIntercepts)sx.push(...a.intercepts.x.map(p=>p.x));const sy=[...a.extrema.map(p=>p.y),...a.horizontal];if(a.intercepts.y)sy.push(a.intercepts.y.y);uniq(sx).forEach(x=>xTick(x));uniq(sy).forEach(y=>yTick(y))}
  else{for(let x=Math.ceil(b.xMin/xStep)*xStep;x<=b.xMax+1e-9;x+=xStep)xTick(x);for(let y=Math.ceil(b.yMin/yStep)*yStep;y<=b.yMax+1e-9;y+=yStep)yTick(y)}
  const xAbove=axisY>H-P.b-24,axisText='font-size="16" font-style="italic" font-family="Georgia,serif" fill="#111827"';parts.push(placeLabel('x',[{x:W-P.r+1,y:axisY+(xAbove?-8:18),anchor:'end'},{x:W-P.r-2,y:axisY+(xAbove?18:-8),anchor:'end',bias:4}],axisText),placeLabel('y',[{x:axisX+10,y:P.t+3,anchor:'start'},{x:axisX-10,y:P.t+3,anchor:'end',bias:4}],axisText));
  if(b.xMin<=0&&b.xMax>=0&&b.yMin<=0&&b.yMax>=0){const originCandidates=[{x:axisX-10,y:axisY+18,anchor:'end'},{x:axisX+10,y:axisY+18,anchor:'start'},{x:axisX-10,y:axisY-8,anchor:'end'},{x:axisX+10,y:axisY-8,anchor:'start'}];parts.push(placeLabel('O',originCandidates,'font-size="12" font-family="Georgia,serif" fill="#111827"'))}
  parts.push(`<g clip-path="url(#${clipId})">`);paths.forEach(ps=>parts.push(`<path d="${ps.map((p,i)=>`${i?'L':'M'} ${X(p.x).toFixed(2)} ${Y(p.y).toFixed(2)}`).join(' ')}" fill="none" stroke="#111827" stroke-width="2.7" stroke-linecap="round" stroke-linejoin="round"/>`));parts.push('</g>');
