  const text=s=>typeof esc==='function'?esc(String(s??'')):String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const nowCode=seed=>String(101+(h(seed)%799));
  const int=(v,min=0,max=999)=>Math.max(min,Math.min(max,parseInt(v,10)||0));
  const fmtMs=ms=>{let s=Math.max(0,Math.round((Number(ms)||0)/1000)),m=Math.floor(s/60);return `${m}:${String(s%60).padStart(2,'0')}`};
  const status=(q,a)=>typeof examQuestionStatus==='function'?examQuestionStatus(q,a):(a==null?'empty':'answered');

  function bank(){try{const rows=window.getPracticeQuestionBank?.();if(Array.isArray(rows))return rows}catch(_){}return typeof state!=='undefined'&&Array.isArray(state.questionBank)?state.questionBank:[]}
  function qualityOk(q){try{let a=window.v361QualityEngine?.auditQuestion?.(q);return !a||!(a.counts?.critical)}catch(_){return true}}
  function eligible(q){if(!q||!q.id||!q.question||!['mcq','tf4','tf','short'].includes(q.type))return false;if(q.reviewStatus&&q.reviewStatus!=='approved'&&q.reviewStatus!=='reviewed')return false;return qualityOk(q)}
  function approvedPool(type){return bank().filter(q=>eligible(q)&&(!type||q.type===type))}
  function recentIds(){try{return new Set(JSON.parse(localStorage.getItem(RECENT_KEY)||'[]'))}catch(_){return new Set()}}
  function pushRecent(ids=[]){try{let old=[...recentIds()],merged=[...ids,...old.filter(x=>!ids.includes(x))].slice(0,160);localStorage.setItem(RECENT_KEY,JSON.stringify(merged))}catch(_){}}
  function normalized(q,section,part){let x=clone(q);x.section=section;x.part=part;return x}
  function diversityKey(q){return String(q.knowledgeCode||q.formId||q.lessonId||q.id||'')}
  function pick(pool,n,seed,levelOrder=['NB','TH','VD','VDC']){
    let recent=recentIds(),src=shuffle(pool,seed),chosen=[],used=new Set(),usedK=new Set();
    const take=(pred,allowRecent=false)=>{let i=src.findIndex(q=>!used.has(q.id)&&pred(q)&&(!recent.has(q.id)||allowRecent)&&!usedK.has(diversityKey(q)));if(i<0)i=src.findIndex(q=>!used.has(q.id)&&pred(q)&&(!recent.has(q.id)||allowRecent));if(i<0)return false;let q=src[i];chosen.push(q);used.add(q.id);usedK.add(diversityKey(q));return true};
    let cursor=0,guard=0;while(chosen.length<n&&guard++<n*8){let lv=levelOrder[cursor++%levelOrder.length];if(!take(q=>q.level===lv,false)&&!take(q=>q.level===lv,true)&&!take(()=>true,false)&&!take(()=>true,true))break}
    return chosen.slice(0,n)
  }
  function baseFullQuestions(){try{return typeof fullExamQuestions==='function'?fullExamQuestions():base.thptExamConfig?.().questions||[]}catch(_){return []}}
