  function readiness(){let p=bank().filter(eligible);return {total:p.length,mcq:p.filter(q=>q.type==='mcq').length,tf4:p.filter(q=>q.type==='tf4').length,short:p.filter(q=>q.type==='short').length,approved:p.filter(q=>q.reviewStatus==='approved').length}}
  function generateOfficial(seed=Date.now()){
    let fb=baseFullQuestions(),code=nowCode(seed),m=pick(approvedPool('mcq'),12,h(`${seed}|I`),['NB','TH','NB','TH','VD','NB','TH','VD']),t=pick(approvedPool('tf4'),4,h(`${seed}|II`),['NB','TH','VD','TH']),s=pick(approvedPool('short'),6,h(`${seed}|III`),['TH','VD','NB','VD','TH','VD']);
    let I=fillWithFallback(m,fb.filter(q=>q.section==='I'),12,'I','Phần I • Nhiều lựa chọn'),II=fillWithFallback(t,fb.filter(q=>q.section==='II'),4,'II','Phần II • Đúng/Sai'),III=fillWithFallback(s,fb.filter(q=>q.section==='III'),6,'III','Phần III • Trả lời ngắn'),questions=[...I,...II,...III];
    let src={bank:I.filter(q=>bank().some(b=>b.id===q.id)).length+II.filter(q=>bank().some(b=>b.id===q.id)).length+III.filter(q=>bank().some(b=>b.id===q.id)).length,fallback:0};src.fallback=questions.length-src.bank;
    return {id:`thpt-v376-${code}-${(Number(seed)>>>0).toString(36)}`,mode:'thpt',title:`Đề thi thử tốt nghiệp THPT • Mã ${code}`,subtitle:'22 câu • 90 phút • 3 dạng thức • Exam Pro',durationMinutes:90,questions,scoring:'thpt',attemptType:'THPT-v37.6',seed:Number(seed)||Date.now(),examCode:code,v376:true,v376Mode:'official',strictExam:true,sourceStats:src,rules:'Thi như thật. Phần I: 12 câu nhiều lựa chọn; Phần II: 4 câu Đúng/Sai; Phần III: 6 câu trả lời ngắn. Hệ thống tự lưu, theo dõi nhịp làm bài và cho kiểm tra toàn bộ câu trước khi nộp.'}
  }
  function generatePractice(size=15,profile='balanced',seed=Date.now()){
    size=int(size,6,30);let all=approvedPool(),levels=profile==='target8'?['TH','VD','VDC','TH','VD']:profile==='foundation'?['NB','NB','TH','NB','TH']:['NB','TH','VD','NB','TH'],qs=pick(all,size,h(`${seed}|practice|${profile}`),levels).map(q=>normalized(q,'P','Luyện đề'));
    return {id:`practice-v376-${profile}-${(Number(seed)>>>0).toString(36)}`,mode:'practice-exam',title:profile==='target8'?'Luyện đề mục tiêu 8+':'Luyện đề thông minh',subtitle:`${qs.length} câu từ ngân hàng • ${profile==='target8'?'ưu tiên TH/VD':'cân bằng mức độ'}`,durationMinutes:Math.max(20,Math.round(qs.length*2.4)),questions:qs,scoring:'normalized',attemptType:`practice-v37.6-${profile}`,seed:Number(seed)||Date.now(),v376:true,v376Mode:'practice',profile,rules:'Luyện theo nhịp đề thi: không hiện đáp án trong lúc làm, tự lưu liên tục, có đánh dấu câu và phân tích lỗi sau khi nộp.'}
  }
  function saveActive(c){try{localStorage.setItem(ACTIVE_KEY,JSON.stringify(c))}catch(_){}}
  function loadActive(){try{let c=JSON.parse(localStorage.getItem(ACTIVE_KEY)||'null');return c?.questions?.length?c:null}catch(_){return null}}
  function activeHasDraft(c=loadActive()){try{return !!(c&&typeof readExamDraft==='function'&&readExamDraft(c))}catch(_){return false}}
  function clearTelemetry(c){try{if(c?.id)localStorage.removeItem(TELEMETRY_PREFIX+c.id)}catch(_){}}
  function loadTelemetry(c){try{return JSON.parse(localStorage.getItem(TELEMETRY_PREFIX+c.id)||'null')}catch(_){return null}}
  function saveTelemetry(){if(!window.examSession?.v376||!examSession.config?.id)return;let x=examSession.v376;try{localStorage.setItem(TELEMETRY_PREFIX+examSession.config.id,JSON.stringify({questionTimes:x.questionTimes,current:examSession.current,enteredAt:x.enteredAt,switches:x.switches||0,updatedAt:Date.now()}))}catch(_){}}
  function commitTime(){let x=window.examSession?.v376;if(!x||!examSession.startedAt||examSession.submitted)return;let now=Date.now(),delta=Math.max(0,Math.min(10*60*1000,now-(x.enteredAt||now))),i=examSession.current;x.questionTimes[i]=(Number(x.questionTimes[i])||0)+delta;x.enteredAt=now;saveTelemetry()}
  function initTelemetry(resume=false){if(!window.examSession)return;let old=resume?loadTelemetry(examSession.config):null,n=examSession.config.questions.length;examSession.v376={questionTimes:Array.isArray(old?.questionTimes)?old.questionTimes.slice(0,n):Array(n).fill(0),enteredAt:Date.now(),switches:Number(old?.switches)||0};while(examSession.v376.questionTimes.length<n)examSession.v376.questionTimes.push(0);saveTelemetry()}
  function sectionTimes(qs,times){let o={I:0,II:0,III:0,P:0};qs.forEach((q,i)=>o[q.section] = (o[q.section]||0)+(Number(times?.[i])||0));return o}
  function currentElapsed(){let x=examSession?.v376;if(!x)return 0;return (Number(x.questionTimes?.[examSession.current])||0)+Math.max(0,Date.now()-(x.enteredAt||Date.now()))}
  function pace(){if(!examSession?.startedAt)return {label:'—',cls:''};let elapsed=Date.now()-examSession.startedAt,total=examSession.config.durationMinutes*60000,done=(examSession.current+1)/Math.max(1,examSession.config.questions.length),target=total*done,diff=elapsed-target;if(Math.abs(diff)<90e3)return {label:'Đúng nhịp',cls:'good'};if(diff>0)return {label:`Chậm ${Math.ceil(diff/60000)}′`,cls:'warn'};return {label:`Nhanh ${Math.ceil(-diff/60000)}′`,cls:'good'}
  }
  function updateRibbon(){if(!examSession?.startedAt)return;let qs=examSession.config.questions,stats=qs.map((q,i)=>status(q,examSession.answers[i])),done=stats.filter(x=>x==='answered').length,partial=stats.filter(x=>x==='partial').length,pct=Math.round((done+.5*partial)*100/Math.max(1,qs.length)),bar=document.querySelector('.v376-progress-line span');if(bar)bar.style.width=pct+'%';let l=document.getElementById('v376ProgressLabel');if(l)l.textContent=`${done}/${qs.length} câu hoàn thành`;let qtime=document.getElementById('v376QuestionTime');if(qtime)qtime.textContent=`⏱ Câu này ${fmtMs(currentElapsed())}`;let p=pace(),pc=document.getElementById('v376Pace');if(pc){pc.textContent=p.label;pc.className=`v376-chip ${p.cls}`};let net=document.getElementById('v376Network');if(net){net.textContent=navigator.onLine?'● Online':'● Offline';net.className=`v376-chip ${navigator.onLine?'good':'offline'}`}}
  function decorateRunner(){let view=document.getElementById('examView');if(!view||!examSession?.startedAt)return;let top=view.querySelector('.exam-top');if(top&&!view.querySelector('.v376-exam-ribbon'))top.insertAdjacentHTML('afterend',`<div class="v376-exam-ribbon"><div class="v376-progress-wrap"><div class="v376-progress-line"><span style="width:0"></span></div><div class="v376-progress-label"><span id="v376ProgressLabel">0/${examSession.config.questions.length} câu hoàn thành</span><span>${text(examSession.config.examCode?`Mã ${examSession.config.examCode}`:'Exam Pro ')}</span></div></div><div class="v376-ribbon-chips"><span id="v376Pace" class="v376-chip">—</span><span id="v376Network" class="v376-chip good">● Online</span><button class="exam-btn" onclick="v376ToggleFocus()">Tập trung</button></div></div>`);let qh=view.querySelector('.exam-question-head>div');if(qh&&!document.getElementById('v376QuestionTime'))qh.insertAdjacentHTML('beforeend','<div id="v376QuestionTime" class="v376-qtime">⏱ Câu này 0:00</div>');updateRibbon()}
  function decorateNavigator(){let side=document.getElementById('examSide');if(!side||side.querySelector('.v376-side-tools'))return;side.insertAdjacentHTML('beforeend',`<div class="v376-side-tools"><button class="exam-btn" onclick="v376ToggleFocus()">◫ Chế độ tập trung</button><button class="exam-btn" onclick="toggleExamFullscreen()">⛶ Toàn màn hình</button><button class="exam-btn" onclick="v376ShowShortcuts()">⌨ Phím tắt</button><div class="v376-shortcuts">←/→ chuyển câu • A–D hoặc 1–4 chọn đáp án • F đánh dấu • Ctrl+Enter kiểm tra trước khi nộp.</div></div>`)}
  function toggleFocus(){document.getElementById('examApp')?.classList.toggle('v376-focus');examToast?.(document.getElementById('examApp')?.classList.contains('v376-focus')?'Đã bật chế độ tập trung.':'Đã hiện lại danh sách câu.')}
  function showShortcuts(){examToast?.('Phím tắt: ←/→ chuyển câu • A–D/1–4 chọn MCQ • F đánh dấu • Ctrl+Enter kiểm tra nộp bài.')}
  function submitReview(){if(!examSession)return;let old=document.getElementById('v376SubmitReview');old?.remove();let qs=examSession.config.questions,st=qs.map((q,i)=>status(q,examSession.answers[i])),done=st.filter(x=>x==='answered').length,partial=st.filter(x=>x==='partial').length,empty=st.filter(x=>x==='empty').length,flagged=examSession.flags.filter(Boolean).length;let div=document.createElement('div');div.id='v376SubmitReview';div.className='v376-submit-backdrop';div.innerHTML=`<div class="v376-submit-card"><h3>Kiểm tra trước khi nộp</h3><p>Hệ thống đã tự lưu bài. Hãy kiểm tra các câu chưa hoàn thành hoặc đã đánh dấu trước khi kết thúc lượt thi.</p><div class="v376-submit-grid"><div class="v376-submit-stat"><b>${done}</b><small>Hoàn thành</small></div><div class="v376-submit-stat"><b>${empty+partial}</b><small>Chưa hoàn tất</small></div><div class="v376-submit-stat"><b>${flagged}</b><small>Đánh dấu</small></div></div>${empty+partial?`<div class="v376-submit-warning">Còn <b>${empty+partial}</b> câu chưa hoàn tất. Thầy/cô/học sinh có thể quay lại kiểm tra trước khi nộp.</div>`:'<div class="v376-submit-warning" style="background:#edf8f1;border-color:#cce8d7;color:#276443">Tất cả câu đã được trả lời đầy đủ.</div>'}<div class="v376-submit-actions"><button class="exam-btn" onclick="v376CloseSubmitReview()">Quay lại làm bài</button>${empty+partial?'<button class="exam-btn" onclick="v376GoFirstIncomplete()">Tới câu chưa làm</button>':''}<button class="exam-btn primary" onclick="v376SubmitNow()">Nộp bài</button></div></div>`;document.getElementById('examApp')?.appendChild(div)}
