    if(base.go)window.goExamQuestion=function(i){commitTime();let before=examSession?.current,r=base.go(i);if(examSession?.v376&&examSession.current!==before){examSession.v376.switches++;examSession.v376.enteredAt=Date.now();saveTelemetry()}return r};
