    if(base.confirmSubmit)window.confirmExamSubmit=submitReview;
    if(base.renderResult)window.renderExamResult=function(result,used,answered,auto){let r=base.renderResult(result,used,answered,auto),times=lastSubmitSnapshot?.questionTimes||examSession?.v376?.questionTimes||[];let review=[...document.querySelectorAll('.exam-result-section')].find(x=>/Xem lại bài làm/i.test(x.querySelector('h3')?.textContent||''));review?.insertAdjacentHTML('beforebegin',analysisHTML(result,times));let wrong=(result.details||[]).filter(d=>!d.ok).map(d=>clone(d.q));try{localStorage.setItem(LAST_WRONG_KEY,JSON.stringify({date:new Date().toISOString(),questions:wrong}))}catch(_){};return r};
