   tool:['book','calculator','compass','ruler'][i%4],shape:i%4===0?'crown':i%4===1?'scholar':i%4===2?'beanie':'cap',
   topStyle:['hoodie','jacket','blazer','robe'][i%4],bottomStyle:['trousers','jogger','pleated','shorts'][i%4],
