function mastery(){try{return window.v382Journey?.mastery?.()||window.v363MasteryEngine?.masterySummary?.()||{counts:{mastered:0},average:null}}catch(_){return {counts:{mastered:0},average:null}}}
function lessonPassCount(){try{return Object.keys(window.v379Economy?.profile?.().rewardLedger?.lessonPass||{}).length}catch(_){return 0}}
function uniqueCorrect(){return new Set(allResults().filter(x=>x?.correct&&x?.questionId).map(x=>x.questionId)).size}
function longestStreak(){const days=[...new Set(attempts().map(a=>{const d=new Date(a.date||a.submittedAt||a.createdAt||0);return isNaN(d)?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}).filter(Boolean))].sort();if(!days.length)return 0;let best=1,cur=1;for(let i=1;i<days.length;i++){const a=new Date(days[i-1]+'T12:00:00'),b=new Date(days[i]+'T12:00:00');if(Math.round((b-a)/86400000)===1){cur++;best=Math.max(best,cur)}else cur=1}return best}
function perfectCount(){return attempts().filter(a=>Number(a.score)>=9.95).length}
