const defs=[
 {id:'first-step',group:'learning',icon:'🚀',title:'Bước đầu tiên',desc:'Hoàn thành bài luyện/đề đầu tiên.',target:1,value:()=>attempts().length,reward:{gold:30}},
 {id:'ten-attempts',group:'learning',icon:'📚',title:'Chăm chỉ 10',desc:'Hoàn thành 10 lượt luyện tập hoặc kiểm tra.',target:10,value:()=>attempts().length,reward:{gold:80}},
 {id:'fifty-correct',group:'learning',icon:'✅',title:'50 câu chuẩn',desc:'Trả lời đúng 50 câu hỏi khác nhau.',target:50,value:uniqueCorrect,reward:{gold:120}},
 {id:'lesson-five',group:'learning',icon:'🎓',title:'Học xong 5 bài',desc:'Vượt mốc đạt bài học ở 5 bài.',target:5,value:lessonPassCount,reward:{item:'back-master-function'}},
 {id:'perfect-one',group:'performance',icon:'👑',title:'Perfect 10',desc:'Đạt điểm 10 một bài thi/luyện.',target:1,value:perfectCount,reward:{item:'head-perfect-10'}},
 {id:'perfect-five',group:'performance',icon:'🏆',title:'Perfect ×5',desc:'Đạt điểm 10 ở 5 lượt khác nhau.',target:5,value:perfectCount,reward:{gold:300}},
 {id:'streak-seven',group:'habit',icon:'🔥',title:'Streak 7 ngày',desc:'Có hoạt động luyện tập 7 ngày liên tiếp.',target:7,value:longestStreak,reward:{item:'aura-streak-7'}},
 {id:'streak-fourteen',group:'habit',icon:'🌟',title:'Streak 14 ngày',desc:'Duy trì chuỗi học tập 14 ngày liên tiếp.',target:14,value:longestStreak,reward:{gold:400}},
 {id:'level-five',group:'journey',icon:'⚡',title:'Lv.5 Học viên',desc:'Đạt cấp độ 5.',target:5,value:level,reward:{gold:100}},
 {id:'level-ten',group:'journey',icon:'🧭',title:'Lv.10 Nhà thám hiểm',desc:'Đạt cấp độ 10.',target:10,value:level,reward:{item:'pet-v386-3'}},
 {id:'level-twenty',group:'journey',icon:'💠',title:'Lv.20 Học giả',desc:'Đạt cấp độ 20.',target:20,value:level,reward:{item:'aura-v386-5'}},
 {id:'master-five',group:'mastery',icon:'∑',title:'Mastery 5',desc:'Làm chủ 5 mã kiến thức.',target:5,value:mastered,reward:{item:'pet-master-derivative'}},
 {id:'master-fifteen',group:'mastery',icon:'∫',title:'Mastery 15',desc:'Làm chủ 15 mã kiến thức.',target:15,value:mastered,reward:{gold:350}},
 {id:'strong-three-lessons',group:'mastery',icon:'📈',title:'3 bài vững chắc',desc:'Có ít nhất 3 bài đạt mastery trung bình từ 80%.',target:3,value:lessonsStrong,reward:{item:'back-v386-9'}},
 {id:'collector-ten',group:'collection',icon:'🎒',title:'Nhà sưu tầm',desc:'Sở hữu 10 vật phẩm Mega Shop.',target:10,value:shopOwned,reward:{gold:150}},
 {id:'legend-three',group:'collection',icon:'💎',title:'Bộ sưu tập Legendary',desc:'Sở hữu 3 vật phẩm Legendary.',target:3,value:legendaryOwned,reward:{item:'bg-v386-10'}}
];
function blank(){return {schemaVersion:SCHEMA,ownerUid:uid(),unlocked:{},updatedAt:''}}
function bucket(){state.achievementV388ByUser=state.achievementV388ByUser&&typeof state.achievementV388ByUser==='object'?state.achievementV388ByUser:{};return state.achievementV388ByUser}
function profile(){const r=bucket()[uid()]||blank();return {...blank(),...r,ownerUid:uid(),unlocked:r.unlocked&&typeof r.unlocked==='object'?r.unlocked:{}}}
function persist(p,{cloud=true}={}){p={...p,schemaVersion:SCHEMA,ownerUid:uid(),updatedAt:now()};bucket()[uid()]=p;try{window.save?.({sync:false,reason:'achievement-v38.8'})}catch(_){};if(cloud&&firebaseUser&&firebaseDb&&!firebaseAccountLocked)firebaseDb.collection('users').doc(firebaseUser.uid).set({achievementV388:p,updatedAt:firebaseServerTimestamp()},{merge:true}).catch(e=>console.warn(' achievement sync',e));return p}
function isDone(d){return Number(d.value())>=d.target}
function rewardText(r={}){if(r.item){const it=window.v386MegaShop?.item?.(r.item);return `🎁 ${it?.label||'Vật phẩm độc quyền'}`}if(r.gold)return `🪙 ${r.gold} vàng`;return 'Danh hiệu'}
function ensureUnlocks(){if(busy)return profile();busy=true;try{const p=profile(),newly=[];for(const d of defs){if(p.unlocked[d.id]||!isDone(d))continue;p.unlocked[d.id]={at:now(),reward:d.reward};newly.push(d)}if(newly.length)persist(p);for(const d of newly){if(d.reward?.item)window.v386MegaShop?.grantItem?.(d.reward.item,`achievement:${d.id}`);if(d.reward?.gold)window.v379Economy?.grant?.({gold:d.reward.gold,key:`achievement:${d.id}`,source:'achievement'});try{window.examToast?.(`🏆 Thành tích: ${d.title}`)}catch(_){}}return p}finally{busy=false}}
function groupLabel(g){return {all:'Tất cả',learning:'Học tập',performance:'Thành tích điểm',habit:'Thói quen',journey:'Cấp độ',mastery:'Mastery',collection:'Sưu tầm'}[g]||g}
function render(){const root=document.getElementById('v388CollectionsPage');if(!root)return;const p=ensureUnlocks(),list=defs.filter(d=>activeGroup==='all'||d.group===activeGroup),done=defs.filter(d=>p.unlocked[d.id]).length;root.innerHTML=`<div class="v388-hero"><div><div class="avatar-preview-kicker">ACHIEVEMENT COLLECTIONS</div><h2>Phòng thành tích học tập</h2><p>Thành tích được tính từ hoạt động học thật, điểm số, streak, level và Mastery. Phần thưởng chỉ là cosmetic/vàng, không tạo lợi thế khi làm bài.</p></div><div class="v388-score"><b>${done}/${defs.length}</b><small>thành tích đã mở</small></div></div><div class="v388-tabs">${['all','learning','performance','habit','journey','mastery','collection'].map(g=>`<button class="${activeGroup===g?'active':''}" onclick="v388Achievements.setGroup('${g}')">${groupLabel(g)}</button>`).join('')}</div><div class="v388-grid">${list.map(d=>{const val=Math.max(0,Number(d.value())||0),ok=!!p.unlocked[d.id],pct=Math.min(100,Math.round(val*100/Math.max(1,d.target)));return `<article class="v388-ach ${ok?'done':'locked'}"><div class="v388-ach-icon">${d.icon}</div><div><h4>${d.title}</h4><p>${d.desc}</p><div class="v388-progress"><i style="width:${pct}%"></i></div><div class="v388-ach-foot"><span>${Math.min(val,d.target)}/${d.target}</span><span class="v388-reward">${rewardText(d.reward)}</span></div></div>${ok?'<span class="v388-done-badge">✓ Đã mở</span>':''}</article>`}).join('')}</div><div class="card mt"><div class="section-head"><div><h3>Kệ cúp của em</h3><p>Những cột mốc đã đạt sẽ xuất hiện ở đây như một bộ sưu tập lâu dài.</p></div></div><div class="v388-shelf">${defs.slice(0,12).map(d=>`<div class="v388-trophy ${p.unlocked[d.id]?'':'empty'}"><span>${d.icon}</span><b>${d.title}</b><small>${p.unlocked[d.id]?'Đã đạt':'Chưa mở'}</small></div>`).join('')}</div></div><div class="v388-stats"><div class="v388-stat"><small>Perfect 10</small><b>${perfectCount()}</b></div><div class="v388-stat"><small>Streak dài nhất</small><b>${longestStreak()} ngày</b></div><div class="v388-stat"><small>Mã mastered</small><b>${mastered()}</b></div><div class="v388-stat"><small>Vật phẩm sở hữu</small><b>${shopOwned()}</b></div></div>`}
function setGroup(g){activeGroup=g;render()}
function inject(){try{ROLE_ACCESS.student.add('collections')}catch(_){};const nav=document.querySelector('[data-nav-group="student-world"] .nav-group-items');if(nav&&!nav.querySelector('[data-page="collections"]'))nav.insertAdjacentHTML('beforeend','<button data-page="collections" title="Bộ sưu tập thành tích"><span class="ico">🏆</span><span class="nav-label">Bộ sưu tập</span></button>');const main=document.querySelector('main .content')||document.querySelector('main');if(main&&!document.getElementById('page-collections'))main.insertAdjacentHTML('beforeend','<section class="section student-only" id="page-collections"><div id="v388CollectionsPage"></div></section>')}
function adoptCloud(){const c=firebaseProfile?.achievementV388;if(!c)return;const l=profile(),ct=Date.parse(c.updatedAt||0)||0,lt=Date.parse(l.updatedAt||0)||0;if(ct>=lt){bucket()[uid()]={...blank(),...c,ownerUid:uid()};try{window.save?.({sync:false,reason:'achievement-cloud-v38.8'})}catch(_){}}}
function install(){inject();if(typeof window.goPage==='function'&&!window.goPage.__v388){const base=window.goPage;const wrap=function(page,internal=false){const r=base(page,internal);if(page==='collections')requestAnimationFrame(render);return r};wrap.__v388=true;window.goPage=wrap}if(typeof window.firebaseHydrateUser==='function'&&!window.firebaseHydrateUser.__v388){const base=window.firebaseHydrateUser;const wrap=async function(u){const r=await base(u);adoptCloud();ensureUnlocks();return r};wrap.__v388=true;window.firebaseHydrateUser=wrap}['math12hub:attempt-rewarded','math12hub:game-reward','math12hub:state-saved'].forEach(ev=>window.addEventListener(ev,()=>{setTimeout(()=>{ensureUnlocks();if(document.getElementById('page-collections')?.classList.contains('active'))render()},80)}));setTimeout(()=>{ensureUnlocks();render()},800)}
window.v388Achievements={build:BUILD,schema:SCHEMA,defs,profile,ensureUnlocks,render,setGroup,longestStreak,perfectCount};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
