function favoriteKey(){return 'math12hub-avatar-favorites-v40194'}
function favoriteSet(){try{return new Set(JSON.parse(localStorage.getItem(favoriteKey())||'[]'))}catch(_){return new Set()}}
function saveFavoriteSet(set){try{localStorage.setItem(favoriteKey(),JSON.stringify([...set]))}catch(_){}}
function isFavorite(id){return favoriteSet().has(String(id||''))}
function toggleFavorite(id){const set=favoriteSet(),key=String(id||'');if(set.has(key))set.delete(key);else set.add(key);saveFavoriteSet(set);renderShopPage();return set.has(key)}
function isNewShopItem(it){return /v391-(1[8-9]|2[0-4])$/.test(String(it?.id||''))||/new|campus|2026/i.test(String(it?.collection||''))}
function shopOwned(it){return !!window.v386MegaShop?.owned?.(it.id)}
function shopEquipped(it){return !!window.v386MegaShop?.equipped?.(it.id)}
function filteredShopItems(){
  let list=(window.v386MegaShop?.catalog||[]).slice();
  if(state.shopSlot!=='all') list=list.filter(x=>x.slot===state.shopSlot);
  if(state.shopRarity!=='all') list=list.filter(x=>(x.rarity||'common')===state.shopRarity);
  if(state.shopSearch) list=list.filter(x=>(String(x.label||'')+' '+String(x.collection||'')).toLowerCase().includes(state.shopSearch.toLowerCase()));
  if(state.shopView==='owned') list=list.filter(shopOwned); else if(state.shopView==='worn') list=list.filter(shopEquipped); else if(state.shopView==='favorite') list=list.filter(x=>isFavorite(x.id)); else if(state.shopView==='new') list=list.filter(isNewShopItem);
  list.sort((a,b)=> state.shopSort==='price' ? (a.price??999999)-(b.price??999999) : state.shopSort==='level' ? (a.level||1)-(b.level||1) : state.shopSort==='rarity' ? (rarityRank[a.rarity]??0)-(rarityRank[b.rarity]??0) : (a.shop===false?1:0)-(b.shop===false?1:0) || (rarityRank[b.rarity]??0)-(rarityRank[a.rarity]??0) || (a.level||1)-(b.level||1));
  return list;
}
